// src/main.rs
use std::{
    fs::File,
    io::{BufReader, Result as IoResult},
    net::SocketAddr,
    sync::Arc,
};

use axum::{
    extract::State,
    http::{HeaderMap, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Json},
    routing::post,
    Router,
};
use rustls::{Certificate, PrivateKey, ServerConfig};
use serde::{Deserialize, Serialize};
use tokio::net::TcpListener;
use tokio_rustls::TlsAcceptor;
use tower_http::{
    cors::{Any, CorsLayer},
    secure_headers::{self, ReferrerPolicy, StrictTransportSecurity},
    trace::TraceLayer,
};
use tracing::{error, info};
use validator::{Validate, ValidationErrors};

#[derive(Deserialize, Validate)]
struct CreateUser {
    #[validate(email)]
    email: String,
    #[validate(length(min = 8))]
    password: String,
}

#[derive(Serialize)]
struct Resp {
    message: String,
}

// ---------- middlewares ----------
async fn security_headers<B>(req: axum::http::Request<B>, next: Next<B>) -> impl IntoResponse {
    let mut resp = next.run(req).await;
    let headers = resp.headers_mut();
    headers.insert(
        axum::http::header::STRICT_TRANSPORT_SECURITY,
        strict_transport_security().to_string().parse().unwrap(),
    );
    headers.insert(
        axum::http::header::REFERRER_POLICY,
        ReferrerPolicy::NoReferrer.to_string().parse().unwrap(),
    );
    headers.insert(
        axum::http::header::X_CONTENT_TYPE_OPTIONS,
        "nosniff".parse().unwrap(),
    );
    resp
}

// ---------- handlers ----------
async fn create_user(
    Json(payload): Json<CreateUser>,
) -> Result<(StatusCode, Json<Resp>), (StatusCode, String)> {
    if let Err(e) = payload.validate() {
        return Err((StatusCode::BAD_REQUEST, format_validation(e)));
    }

    // TODO: hash password (argon2) + DB insert via prepared stmt
    Ok((
        StatusCode::CREATED,
        Json(Resp {
            message: "Usuário criado com segurança".into(),
        }),
    ))
}

// ---------- utils ----------
fn format_validation(err: ValidationErrors) -> String {
    err.field_errors()
        .iter()
        .map(|(f, e)| format!("{}: {}", f, e[0].code))
        .collect::<Vec<_>>()
        .join("; ")
}

fn load_tls_config() -> IoResult<ServerConfig> {
    // supõe que cert/key são providos por secret manager ou volume montado
    let cert_file = &mut BufReader::new(File::open("cert.pem")?);
    let key_file = &mut BufReader::new(File::open("key.pem")?);
    let certs = rustls_pemfile::certs(cert_file)?
        .into_iter()
        .map(Certificate)
        .collect();
    let mut keys = rustls_pemfile::pkcs8_private_keys(key_file)?;
    let key = PrivateKey(keys.remove(0));
    let mut cfg = ServerConfig::builder()
        .with_safe_defaults()
        .with_no_client_auth()
        .with_single_cert(certs, key)?;
    cfg.max_fragment_size = Some(16384);
    cfg.versions = vec![rustls::ProtocolVersion::TLSv1_3];
    Ok(cfg)
}

// ---------- main ----------
#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();

    let app = Router::new()
        .route("/users", post(create_user))
        .layer(middleware::from_fn(security_headers))
        .layer(
            CorsLayer::new()
                .allow_origin(Any)
                .allow_methods(Any)
                .allow_headers(Any),
        )
        .layer(TraceLayer::new_for_http());

    let addr: SocketAddr = "0.0.0.0:8443".parse()?;
    let listener = TcpListener::bind(addr).await?;
    let tls_cfg = load_tls_config()?;
    let tls_acceptor = TlsAcceptor::from(Arc::new(tls_cfg));

    info!("Servidor seguro ouvindo em https://{}", addr);
    loop {
        let (stream, _) = listener.accept().await?;
        let acceptor = tls_acceptor.clone();
        let svc = app.clone();
        tokio::spawn(async move {
            let tls_stream = match acceptor.accept(stream).await {
                Ok(s) => s,
                Err(e) => {
                    error!("TLS handshake failed: {}", e);
                    return;
                }
            };
            if let Err(e) = axum::serve::serve_connection(tls_stream, svc).await {
                error!("Request handling error: {}", e);
            }
        });
    }
}
```

**O que foi mesclado**

- Segurança de memória e concorrência do **Rust** (modelo ownership).  
- TLS 1.3 obrigatório (`load_tls_config`).  
- Middleware de *security headers* (HSTS, Referrer‑Policy, nosniff).  
- CORS restrito via `tower-http`.  
- Logging estruturado com `tracing`.  
- Validação de entrada usando `validator`.  
- Esqueleto pronto para inserir hash de senha e acesso ao DB de forma segura.

### Falhas reais no consenso
1. **Ausência de HTTPS/TLS no código Rust** – o exemplo roda HTTP puro (`TcpListener::bind`), inviável para produção segura.
2. **Validação apenas sintática** – `validator` checa formato, mas não sanitiza contra injeção (ex.: SQL/NoSQL) nem aplica *allow-list* de caracteres.
3. **Falta de headers de segurança e rate limiting** – CSP, HSTS, `X-Content-Type-Options`, `Referrer-Policy` e limitação de requisições não existem no snippet.

