use axum::{
    extract::Json,
    http::{header, StatusCode},
    routing::post,
    Router,
};
use serde::{Deserialize, Serialize};
use std::time::Duration;
use tower_http::{
    set_header::SetResponseHeaderLayer,
    timeout::TimeoutLayer,
};
use validator::Validate;

#[derive(Deserialize, Validate)]
struct CreateUser {
    #[validate(email(message = "E-mail inválido"))]
    email: String,
    #[validate(length(min = 8, max = 72, message = "A senha deve ter entre 8 e 72 caracteres"))]
    password: String,
}

#[derive(Serialize)]
struct ResponseMessage {
    message: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Inicialização do tracing (logs sem dados sensíveis/PII)
    tracing_subscriber::fmt()
        .with_target(false)
        .compact()
        .init();

    // Camadas de segurança defensiva (Timeouts contra Slowloris e Headers de Borda)
    let app = Router::new()
        .route("/users", post(create_user))
        .layer(SetResponseHeaderLayer::if_not_present(
            header::X_CONTENT_TYPE_OPTIONS,
            header::HeaderValue::from_static("nosniff"),
        ))
        .layer(SetResponseHeaderLayer::if_not_present(
            header::STRICT_TRANSPORT_SECURITY,
            header::HeaderValue::from_static("max-age=31536000; includeSubDomains"),
        ))
        .layer(TimeoutLayer::new(Duration::from_secs(10)));

    let listener = tokio::net::TcpListener::bind("127.0.0.1:8443").await?;
    tracing::info!("Backend seguro rodando em https://127.0.0.1:8443");

    // SUPOSIÇÃO: O certificado TLS 1.3 obrigatório é aplicado no listener via rustls ou proxy reverso na borda.
    axum::serve(listener, app).await?;
    Ok(())
}

