    Json(payload): Json<CreateUser>,
) -> Result<(StatusCode, Json<ResponseMessage>), (StatusCode, String)> {
    payload.validate().map_err(|e| {
        (StatusCode::BAD_REQUEST, format!("Erro de validação: {}", e))
    })?;

    // SUPOSIÇÃO: O hash da senha é feito com Argon2id e a persistência usa SQL parametrizado (ex: sqlx).

